import assert from 'node:assert/strict';
import {emptyContacts,nextContactSummary} from '../src/contact.ts';
test('student email corrections require Super Admin and atomic immutable history while all identity and project permissions remain unchanged',async()=>{
 const id='student-contact-email';await seedWorkflow(id);await env.withSecurityRulesDisabled(async c=>{await updateDoc(doc(c.firestore(),'students',id),{email:'',name:'Synthetic contact student'});});
 async function change(uid='admin',event='email-one',email='student@example.edu',options={}){const db=env.authenticatedContext(uid).firestore(),ref=doc(db,'students',id),b=writeBatch(db);if(options.student!==false)b.update(ref,{email,lastEmailEventId:event,emailUpdatedBy:uid,emailUpdatedAt:serverTimestamp(),...options.studentChanges});if(options.audit!==false)b.set(doc(ref,'emailHistory',event),{email,previousEmail:options.previousEmail??'',reason:'Synthetic confirmed contact correction',confirmed:true,actorId:uid,actorName:uid,createdAt:serverTimestamp(),...options.auditChanges});return b.commit();}
 for(const uid of['sup','co','hod-a','hod-b','other','foreign','inactive','unknown'])await assertFails(change(uid));await assertFails(change('admin','no-history','student@example.edu',{audit:false}));await assertFails(change('admin','orphan','student@example.edu',{student:false}));
 for(const email of['a@example.edu,b@example.edu','a@example.edu\nBcc: b@example.edu','a..b@example.edu','a@-example.edu','a@example..edu',123,''])await assertFails(change('admin','invalid-email',email));
 for(const studentChanges of[{name:'Another student'},{departmentId:'dept-b'},{session:'2024/2025'},{matricNumber:'changed'},{emailUpdatedBy:'hod-a'}])await assertFails(change('admin','identity-change','student@example.edu',{studentChanges}));
 for(const auditChanges of[{confirmed:false},{reason:' '},{reason:'x'.repeat(501)},{actorName:'Fake'},{previousEmail:'old@example.edu'},{email:'different@example.edu'},{extra:'unapproved field'}])await assertFails(change('admin','bad-audit','student@example.edu',{auditChanges}));
 await assertSucceeds(change()).catch(e=>{throw Error('Atomic student email update: '+e.message);});
 for(const uid of['sup','co','hod-a','admin']){const record=await assertSucceeds(getDoc(doc(env.authenticatedContext(uid).firestore(),'students',id)));if(record.data().email!=='student@example.edu')throw Error('Current permitted readers must see the updated email.');}
 for(const uid of['sup','co','hod-a','hod-b','other','foreign','inactive','unknown'])await assertFails(getDoc(doc(env.authenticatedContext(uid).firestore(),'students',id,'emailHistory','email-one')));
 const admin=env.authenticatedContext('admin').firestore();await assertSucceeds(getDocs(collection(admin,'students',id,'emailHistory')));await assertFails(getDoc(doc(admin,'projects',id)));await assertFails(change('admin','stale','new@example.edu'));await assertFails(change('admin','email-one','new@example.edu',{previousEmail:'student@example.edu'}));
 await assertSucceeds(change('admin','email-two','new@example.edu',{previousEmail:'student@example.edu'}));await assertSucceeds(change('admin','email-clear','',{previousEmail:'new@example.edu'}));
 await assertFails(updateDoc(doc(admin,'students',id,'emailHistory','email-one'),{reason:'Changed history'}));await assertFails(deleteDoc(doc(admin,'students',id,'emailHistory','email-one')));await assertFails(deleteDoc(doc(admin,'students',id)));
});
test('Super Admin intake policies require immutable audits and gate new receipts and reviews without hiding history',async()=>{
 const id='intake-policy-project';await seedWorkflow(id);await topicDecision(id);const sup=env.authenticatedContext('sup').firestore(),admin=env.authenticatedContext('admin').firestore();
 const oldHash='1'.repeat(64),newHash='2'.repeat(64);const metadata=(fileName,size)=>({fileName,size,pages:1,createdBy:'sup',createdAt:serverTimestamp()});
 await assertSucceeds(setDoc(doc(sup,'projects',id,'documentReviews',oldHash),metadata('previous.docx',2*1048576)));
 async function policy(uid='admin',revision='intake-one',changes={},audit=true,previous={previousMaxMiB:20,previousPdf:true,previousWord:true}){const db=env.authenticatedContext(uid).firestore(),ref=doc(db,'documentIntakePolicies','dept-a'),b=writeBatch(db),p={maxMiB:1,pdfAllowed:true,wordAllowed:false,note:'Synthetic department intake decision',revision,updatedBy:uid,updatedAt:serverTimestamp(),...changes};b.set(ref,p);if(audit)b.set(doc(ref,'history',revision),{...p,...previous,actorName:uid});return b.commit();}
 try {
  for(const uid of['sup','co','hod-a','hod-b','foreign','inactive','unknown'])await assertFails(policy(uid));
  await assertFails(policy('admin','no-audit',{},false));for(const changes of[{maxMiB:0},{maxMiB:21},{maxMiB:1.5},{pdfAllowed:false},{note:' '},{updatedBy:'hod-a'}])await assertFails(policy('admin','invalid',changes));
  await assertSucceeds(policy()).catch(e=>{throw Error('Intake policy with audit: '+e.message);});
  for(const uid of['sup','co','hod-a','admin'])await assertSucceeds(getDoc(doc(env.authenticatedContext(uid).firestore(),'documentIntakePolicies','dept-a')));
  for(const uid of['hod-b','foreign','inactive','unknown'])await assertFails(getDoc(doc(env.authenticatedContext(uid).firestore(),'documentIntakePolicies','dept-a')));
  await assertFails(getDocs(collection(sup,'documentIntakePolicies','dept-a','history')));await assertSucceeds(getDocs(collection(admin,'documentIntakePolicies','dept-a','history')));
  await assertFails(policy('admin','unchanged',{},true,{previousMaxMiB:1,previousPdf:true,previousWord:false}));await assertFails(policy('admin','intake-one',{maxMiB:2},true,{previousMaxMiB:1,previousPdf:true,previousWord:false}));
  await assertFails(setDoc(doc(sup,'projects',id,'documentReviews',newHash),metadata('new.docx',100)));await assertFails(setDoc(doc(sup,'projects',id,'documentReviews',newHash),metadata('new.pdf',1048577)));await assertSucceeds(setDoc(doc(sup,'projects',id,'documentReviews',newHash),metadata('new.PDF',1048576)));
  await assertSucceeds(getDoc(doc(sup,'projects',id,'documentReviews',oldHash)));
  // Existing saved reviews can still receive remarks after their original type is disabled.
  const b=writeBatch(sup),pref=doc(sup,'projects',id),aid='intake-old-review-remark';b.set(doc(pref,'documentReviews',oldHash,'annotations',aid),{anchorKind:'Text',page:1,pageWidth:595,pageHeight:842,rects:[{x:40,y:700,width:150,height:12}],quote:'Existing passage',comment:'Continue the earlier review.',category:'Content',severity:'Suggestion',actorId:'sup',actorName:'sup',createdAt:serverTimestamp()});b.set(doc(pref,'feedback',aid),{category:'Content',priority:'Suggestion',milestoneKey:'',milestoneName:'Overall project',comment:'Continue the earlier review.',summary:'PDF review: previous.docx, page 1',actorId:'sup',actorName:'sup',createdAt:serverTimestamp()});b.update(pref,{lastFeedbackEventId:aid,lastFeedbackBy:'sup',lastFeedbackAt:serverTimestamp(),updatedBy:'sup',updatedAt:serverTimestamp()});await assertSucceeds(b.commit());
  async function receipt(fileName,size,sourceKind){const ref=doc(sup,'projects',id),batch=writeBatch(sup),rid='policy-receipt';batch.set(doc(ref,'submissionReceipts',rid),{fileName,size,pages:1,sourceKind,sourceHash:'3'.repeat(64),reviewHash:'3'.repeat(64),milestoneKey:'m0',milestoneName:'Proposal',registerId:'stage_m0',version:1,previousReceiptId:'',receivedOn:'2024-02-29',channel:'Email',note:'',actorId:'sup',actorName:'sup',createdAt:serverTimestamp()});batch.set(doc(ref,'submissionRegisters','stage_m0'),{latestReceiptId:rid,version:1,sourceHash:'3'.repeat(64),actorId:'sup',updatedAt:serverTimestamp()});return batch.commit();}
  await assertFails(receipt('draft.docx',100,'Word'));await assertFails(receipt('draft.pdf',1048577,'PDF'));await assertSucceeds(receipt('draft.pdf',1048576,'PDF'));
  await assertFails(updateDoc(doc(admin,'documentIntakePolicies','dept-a','history','intake-one'),{note:'Changed'}));await assertFails(deleteDoc(doc(admin,'documentIntakePolicies','dept-a')));
  await assertFails(policy('admin','bad-previous',{maxMiB:2}));await assertSucceeds(policy('admin','intake-two',{maxMiB:2},true,{previousMaxMiB:1,previousPdf:true,previousWord:false}));
 } finally {await env.withSecurityRulesDisabled(async c=>{await deleteDoc(doc(c.firestore(),'documentIntakePolicies','dept-a'));});}
});
test('chat replies require a live same-conversation root, retain immutable targets and preserve private membership',async()=>{
 const sup=env.authenticatedContext('sup').firestore(),co=env.authenticatedContext('co').firestore();const cid='reply-private';
 await assertSucceeds(setDoc(doc(sup,'chats',cid),{departmentId:'dept-a',kind:'direct',name:'Synthetic reply conversation',memberIds:['sup','co'],createdBy:'sup',createdAt:serverTimestamp()}));
 const message=(uid,replyToId='')=>({body:'Synthetic thread text',senderId:uid,senderName:uid,removed:false,announcement:false,replyToId,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});
 await assertSucceeds(setDoc(doc(sup,'chats',cid,'messages','root'),message('sup')));
 await assertSucceeds(setDoc(doc(co,'chats',cid,'messages','reply'),message('co','root')));
 for(const [id,target]of[['missing-reply','missing'],['nested-reply','reply'],['self-reply','self-reply'],['invalid-path','root/child']])await assertFails(setDoc(doc(co,'chats',cid,'messages',id),message('co',target)));
 for(const uid of['hod-a','admin','other','foreign','inactive-sup','unknown']){const db=env.authenticatedContext(uid).firestore();await assertFails(setDoc(doc(db,'chats',cid,'messages','unauthorized-'+uid),message(uid,'root')));await assertFails(getDoc(doc(db,'chats',cid,'messages','reply')));}
 await assertSucceeds(setDoc(doc(sup,'chats','reply-other-chat'),{departmentId:'dept-a',kind:'direct',name:'Other synthetic conversation',memberIds:['sup','co'],createdBy:'sup',createdAt:serverTimestamp()}));
 await assertFails(setDoc(doc(co,'chats','reply-other-chat','messages','cross-chat'),message('co','root')));
 await assertFails(setDoc(doc(co,'chats',cid,'messages','copied-content'),{...message('co','root'),replyBody:'Original snapshot'}));
 await assertFails(setDoc(doc(co,'chats',cid,'messages','bad-type'),message('co',123)));
 await assertFails(updateDoc(doc(co,'chats',cid,'messages','reply'),{replyToId:'',updatedAt:serverTimestamp()}));
 const simultaneous=writeBatch(sup);simultaneous.update(doc(sup,'chats',cid,'messages','root'),{body:'',removed:true,updatedAt:serverTimestamp()});simultaneous.set(doc(sup,'chats',cid,'messages','reply-with-removal'),message('sup','root'));await assertFails(simultaneous.commit());
 await assertSucceeds(updateDoc(doc(co,'chats',cid,'messages','reply'),{body:'Edited reply',updatedAt:serverTimestamp()}));
 await assertSucceeds(updateDoc(doc(sup,'chats',cid,'messages','root'),{body:'',removed:true,updatedAt:serverTimestamp()}));
 await assertFails(setDoc(doc(co,'chats',cid,'messages','after-removal'),message('co','root')));
 await assertSucceeds(getDoc(doc(co,'chats',cid,'messages','reply')));
 await assertSucceeds(updateDoc(doc(co,'chats',cid,'messages','reply'),{body:'',removed:true,updatedAt:serverTimestamp()}));
 // A legacy root without replyToId remains replyable. Announcements cannot be created as replies.
 await env.withSecurityRulesDisabled(async c=>{await setDoc(doc(c.firestore(),'staff','reply-hod'),{role:'hod',departmentId:'dept-thread',active:true,displayName:'reply-hod'});await setDoc(doc(c.firestore(),'staff','reply-peer'),{role:'lecturer',departmentId:'dept-thread',active:true,displayName:'reply-peer'});});
 const hod=env.authenticatedContext('reply-hod').firestore(),peer=env.authenticatedContext('reply-peer').firestore();await assertSucceeds(setDoc(doc(hod,'chats','general__dept-thread'),{departmentId:'dept-thread',kind:'general',name:'Department channel',memberIds:[],createdBy:'reply-hod',createdAt:serverTimestamp()}));
 const legacy=message('reply-hod');delete legacy.replyToId;await assertSucceeds(setDoc(doc(hod,'chats','general__dept-thread','messages','legacy-reply-root'),legacy));
 await assertSucceeds(setDoc(doc(peer,'chats','general__dept-thread','messages','legacy-child'),message('reply-peer','legacy-reply-root')));
 await assertFails(setDoc(doc(hod,'chats','general__dept-thread','messages','pinned-reply'),{...message('reply-hod','legacy-reply-root'),announcement:true}));
});
test('submission receipts require atomic version heads, current assignments and immutable originals with audited corrections',async()=>{
 const id='submission-receipts';await seedWorkflow(id);await topicDecision(id);const hash='a'.repeat(64),db=env.authenticatedContext('sup').firestore();
 async function record(uid='sup',rid='one',changes={},options={}){const f=env.authenticatedContext(uid).firestore(),pref=doc(f,'projects',id),headRef=doc(pref,'submissionRegisters','stage_m0'),head=(await getDoc(headRef)).data(),batch=writeBatch(f);const data={fileName:'proposal.pdf',size:100,pages:2,sourceKind:'PDF',sourceHash:hash,reviewHash:hash,milestoneKey:'m0',milestoneName:'Proposal',registerId:'stage_m0',version:(head?.version||0)+1,previousReceiptId:head?.latestReceiptId||'',receivedOn:'2024-02-29',channel:'Email',note:'Synthetic received draft',actorId:uid,actorName:uid,createdAt:serverTimestamp(),...changes};batch.set(doc(pref,'submissionReceipts',rid),data);if(options.head!==false)batch.set(headRef,{latestReceiptId:rid,version:data.version,sourceHash:data.sourceHash,actorId:uid,updatedAt:serverTimestamp()});return batch.commit();}
 for(const uid of ['admin','hod-a','hod-b','other','inactive-sup'])await assertFails(record(uid));await assertFails(record('sup','missing-head',{}, {head:false}));for(const changes of [{milestoneName:'Forged stage'},{milestoneKey:'missing'},{receivedOn:'2023-02-29'},{receivedOn:'2099-01-01'},{actorName:'Fake'},{sourceFile:'encoded-content'},{pages:101}])await assertFails(record('sup','invalid',changes));await assertSucceeds(record()).catch(e=>{throw Error('First submission receipt: '+e.message);});await assertFails(record('sup','duplicate'));await assertFails(record('sup','stale',{sourceHash:'b'.repeat(64),previousReceiptId:''}));await assertSucceeds(record('co','two',{sourceHash:'b'.repeat(64),reviewHash:'b'.repeat(64),receivedOn:'2024-02-01'})).catch(e=>{throw Error('Second submission receipt: '+e.message);});
 const ref=doc(db,'projects',id,'submissionReceipts','one');await assertFails(updateDoc(ref,{receivedOn:'2024-02-01'}));await assertFails(deleteDoc(ref));await assertFails(deleteDoc(doc(db,'projects',id,'submissionRegisters','stage_m0')));
 async function correct(uid='sup',event='correction',changes={},audit=true){const f=env.authenticatedContext(uid).firestore(),receipt=doc(f,'projects',id,'submissionReceipts','one'),old=(await getDoc(receipt)).data(),batch=writeBatch(f);const c={correctionRevision:event,correctedReceivedOn:'2024-02-20',correctedChannel:'Drive link',correctedNote:'Corrected receipt note',correctionReason:'Corrected from original email evidence',correctedBy:uid,correctedByName:uid,correctedAt:serverTimestamp(),...changes};batch.update(receipt,c);if(audit)batch.set(doc(receipt,'corrections',event),{...c,previousReceivedOn:old.correctedReceivedOn??old.receivedOn,previousChannel:old.correctedChannel??old.channel,previousNote:old.correctedNote??old.note});return batch.commit();}
 await assertFails(correct('hod-a'));await assertFails(correct('sup','no-audit',{},false));await assertFails(correct('sup','tamper',{fileName:'changed.pdf'}));await assertFails(correct('sup','blank',{correctionReason:' '}));await assertSucceeds(correct()).catch(e=>{throw Error('Audited receipt correction: '+e.message);});await assertFails(correct('sup','unchanged'));await assertSucceeds(correct('co','next',{correctedReceivedOn:'2024-02-19'}));await assertFails(updateDoc(doc(ref,'corrections','correction'),{correctedNote:'Tampered'}));await assertFails(deleteDoc(doc(ref,'corrections','correction')));
 const original=(await getDoc(ref)).data();if(original.receivedOn!=='2024-02-29'||original.correctedReceivedOn!=='2024-02-19')throw Error('Original and corrected dates must both survive.');for(const uid of ['sup','co','hod-a'])await assertSucceeds(getDoc(doc(env.authenticatedContext(uid).firestore(),'projects',id,'submissionReceipts','one')));for(const uid of ['admin','hod-b','foreign','other'])await assertFails(getDoc(doc(env.authenticatedContext(uid).firestore(),'projects',id,'submissionReceipts','one')));
 await env.withSecurityRulesDisabled(async c=>await updateDoc(doc(c.firestore(),'projects',id),{completedDate:'2026-01-01'}));await assertFails(record('sup','archived',{sourceHash:'c'.repeat(64)}));await assertFails(correct('sup','archived',{correctedReceivedOn:'2024-02-18'}));await env.withSecurityRulesDisabled(async c=>await updateDoc(doc(c.firestore(),'projects',id),{supervisorId:'other',coSupervisorId:''}));await assertFails(getDoc(ref));await assertSucceeds(getDoc(doc(env.authenticatedContext('other').firestore(),'projects',id,'submissionReceipts','one')));
});
test('revision transfers preserve lineage, reject addressed or forged source remarks and remain scoped and immutable',async()=>{
 const id='revision-transfer';await seedWorkflow(id);const oldHash='d'.repeat(64),newHash='e'.repeat(64),thirdHash='f'.repeat(64);const original={anchorKind:'Text',page:1,pageWidth:595,pageHeight:842,rects:[{x:50,y:700,width:300,height:15}],quote:'The sampling frame must be explained before analysis.',comment:'Explain the sampling frame.',category:'Methodology',severity:'Major correction',actorId:'sup',actorName:'sup',createdAt:serverTimestamp()};
 await env.withSecurityRulesDisabled(async c=>{const db=c.firestore();await setDoc(doc(db,'projects',id,'documentReviews',oldHash),{fileName:'earlier.pdf',size:100,pages:2,createdBy:'sup',createdAt:serverTimestamp()});await setDoc(doc(db,'projects',id,'documentReviews',oldHash,'annotations','original'),original);await setDoc(doc(db,'projects',id,'documentReviews',oldHash,'annotations','positive'),{...original,severity:'Good point'});});
 async function copy(uid='sup',hash=newHash,sourceId='original',changes={},sourceHash=oldHash){const db=env.authenticatedContext(uid).firestore(),pref=doc(db,'projects',id),ref=doc(pref,'documentReviews',hash),aid=hash+'__original';const exists=await getDoc(ref);const batch=writeBatch(db);if(!exists.exists())batch.set(ref,{fileName:'revised.pdf',size:150,pages:3,createdBy:uid,createdAt:serverTimestamp()});const a={...original,anchorKind:'Area',page:2,actorId:uid,actorName:uid,sourceHash,sourceRemarkId:sourceId,sourceRootId:'original',...changes};batch.set(doc(ref,'annotations',aid),a);batch.set(doc(pref,'feedback',aid),{category:a.category,priority:'Action required',milestoneKey:'',milestoneName:'Overall project',comment:a.comment,summary:'PDF review: revised.pdf, page '+a.page,actorId:uid,actorName:uid,createdAt:serverTimestamp()});batch.update(pref,{lastFeedbackEventId:aid,lastFeedbackBy:uid,lastFeedbackAt:serverTimestamp(),updatedBy:uid,updatedAt:serverTimestamp()});return batch.commit();}
 for(const uid of ['admin','hod-a','hod-b','other','inactive-sup'])await assertFails(copy(uid));for(const changes of [{comment:'Forged source comment'},{sourceRootId:'fake'},{sourceHash:newHash},{sourceRemarkId:'missing'}])await assertFails(copy('sup',newHash,'original',changes));await assertFails(copy('sup',newHash,'positive'));await assertSucceeds(copy()).catch(e=>{throw Error('First revision transfer: '+e.message);});await assertFails(copy());await assertSucceeds(copy('co',thirdHash,newHash+'__original',{},newHash)).catch(e=>{throw Error('Chained revision transfer: '+e.message);});
 const sup=env.authenticatedContext('sup').firestore();const ref=doc(sup,'projects',id,'documentReviews',newHash,'annotations',newHash+'__original');await assertFails(updateDoc(ref,{sourceHash:thirdHash}));await assertFails(deleteDoc(ref));await assertSucceeds(getDoc(doc(env.authenticatedContext('hod-a').firestore(),'projects',id,'documentReviews',oldHash,'annotations','original')));
 await env.withSecurityRulesDisabled(async c=>{await setDoc(doc(c.firestore(),'projects',id,'feedback','original','followUp','current'),{state:'Addressed'});});await assertFails(copy('sup','a'.repeat(64)));await env.withSecurityRulesDisabled(async c=>{await updateDoc(doc(c.firestore(),'projects',id),{supervisorId:'other',coSupervisorId:''});});await assertFails(getDoc(ref));
});
