test('Super Admin moderation atomically removes only an unchanged reported message after review and preserves the private snapshot',async()=>{
 const cid='moderation-private';await env.withSecurityRulesDisabled(async c=>{const db=c.firestore();await setDoc(doc(db,'chats',cid),{departmentId:'dept-a',kind:'direct',name:'Synthetic moderation context',memberIds:['sup','co'],createdBy:'sup',createdAt:serverTimestamp()});for(const id of['remove','changed','not-reviewed','hod-target','already-removed','unrelated']){const msg=doc(db,'chats',cid,'messages',id);await setDoc(msg,{body:'Synthetic source message',senderId:'co',senderName:'co',removed:id==='already-removed',announcement:false,projectRefId:'private-link',createdAt:serverTimestamp(),updatedAt:serverTimestamp()});const m=(await getDoc(msg)).data();await setDoc(doc(db,'chatReports','moderation-'+id),{departmentId:'dept-a',chatId:cid,messageId:id,messageBody:m.body,senderId:'co',senderName:'co',messageCreatedAt:m.createdAt,messageUpdatedAt:m.updatedAt,reporterId:'sup',reporterName:'sup',reason:'Synthetic concern involving HOD',hodSubject:id!=='hod-target',targetRole:id==='hod-target'?'hod':'admin',state:id==='not-reviewed'?'Reported':'Under review',decisionNote:'Synthetic reviewed policy',revision:'initial-review',createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:'admin'});await setDoc(doc(db,'chatReports','moderation-'+id,'history','initial-review'),{state:'Under review',targetRole:'admin',note:'Synthetic review',actorId:'admin',actorName:'admin',createdAt:serverTimestamp()});}await updateDoc(doc(db,'chats',cid,'messages','changed'),{body:'A later edited message',updatedAt:serverTimestamp()});});
 let serial=0;async function remove(uid,id,options={}){const db=env.authenticatedContext(uid).firestore(),rid='moderation-'+id,ref=doc(db,'chatReports',rid),revision='moderation-'+(++serial),batch=writeBatch(db),note='Synthetic reason after institutional review';if(options.message!==false)batch.update(doc(db,'chats',cid,'messages',options.messageId||id),{body:options.body??'',removed:true,moderationReportId:rid,updatedAt:serverTimestamp(),...(options.extra||{})});if(options.report!==false)batch.update(ref,{state:'Message removed',targetRole:'admin',decisionNote:note,revision,updatedBy:uid,updatedAt:serverTimestamp()});if(options.audit!==false)batch.set(doc(ref,'history',revision),{state:'Message removed',targetRole:'admin',note,actorId:uid,actorName:uid,createdAt:serverTimestamp()});return batch.commit();}
 for(const uid of['sup','co','hod-a','hod-b','inactive-sup'])await assertFails(remove(uid,'remove'));for(const options of[{message:false},{report:false},{audit:false},{messageId:'unrelated'},{body:'Replacement text'},{extra:{senderName:'Forged'}}])await assertFails(remove('admin','remove',options));for(const id of['changed','not-reviewed','hod-target','already-removed'])await assertFails(remove('admin',id));await assertSucceeds(remove('admin','remove')).catch(e=>{throw Error('Atomic moderated removal: '+e.message);});
 const admin=env.authenticatedContext('admin').firestore(),co=env.authenticatedContext('co').firestore(),sup=env.authenticatedContext('sup').firestore();const message=(await assertSucceeds(getDoc(doc(co,'chats',cid,'messages','remove')))).data();if(message.body!==''||!message.removed||message.moderationReportId!=='moderation-remove'||message.senderId!=='co'||message.projectRefId!=='private-link')throw Error('Moderation must remove only message text and preserve immutable identity and references.');await assertFails(getDoc(doc(admin,'chats',cid,'messages','remove')));await assertFails(getDocs(collection(admin,'chats',cid,'messages')));const report=(await assertSucceeds(getDoc(doc(sup,'chatReports','moderation-remove')))).data();if(report.messageBody!=='Synthetic source message'||report.state!=='Message removed')throw Error('Original reported text and moderation decision must remain preserved.');const history=await assertSucceeds(getDocs(collection(admin,'chatReports','moderation-remove','history')));if(history.size!==2)throw Error('Review and moderation audit must both persist.');await assertFails(remove('admin','remove'));await assertFails(updateDoc(doc(co,'chats',cid,'messages','remove'),{body:'Restored',removed:false,updatedAt:serverTimestamp()}));await assertFails(updateDoc(doc(admin,'chatReports','moderation-remove'),{state:'Under review',updatedBy:'admin',updatedAt:serverTimestamp()}));await assertFails(deleteDoc(doc(admin,'chatReports','moderation-remove','history',history.docs[0].id)));
});
