 async function save(uid='sup',aid='remark',changes={},options={}){const db=env.authenticatedContext(uid).firestore();const pref=doc(db,'projects',id);const ref=doc(pref,'documentReviews',hash);const before=await getDoc(ref);const batch=writeBatch(db);if(!before.exists())batch.set(ref,{...metadata,createdBy:uid});const value={anchorKind:'Text',page:1,pageWidth:595,pageHeight:842,rects:[{x:40,y:700,width:150,height:12}],quote:'Synthetic passage',comment:'Explain the sampling approach.',category:'Methodology',severity:'Major correction',actorId:uid,actorName:uid,createdAt:serverTimestamp(),...changes};batch.set(doc(ref,'annotations',aid),value);if(options.feedback!==false)batch.set(doc(pref,'feedback',aid),{category:value.category,priority:value.severity==='Major correction'?'Action required':value.severity==='Good point'?'Positive feedback':'Suggestion',milestoneKey:'',milestoneName:'Overall project',comment:value.comment,summary:`PDF review: ${metadata.fileName}, page ${value.page}`,actorId:uid,actorName:uid,createdAt:serverTimestamp()});if(options.parent!==false)batch.update(pref,{lastFeedbackEventId:aid,lastFeedbackBy:uid,lastFeedbackAt:serverTimestamp(),updatedBy:uid,updatedAt:serverTimestamp()});return batch.commit();}
 for(const uid of ['admin','hod-a','hod-b','other','inactive-sup'])await assertFails(save(uid));await assertFails(save('sup','detached',{}, {feedback:false}));await assertFails(save('sup','no-parent',{}, {parent:false}));for(const changes of [{page:3},{actorName:'Fake'},{rects:[{x:-1,y:700,width:100,height:10}]},{rects:[{x:590,y:700,width:100,height:10}]},{rects:[]},{sourceFile:'encoded-file-bytes'}])await assertFails(save('sup','invalid',changes));await assertSucceeds(save()).catch(e=>{throw Error('First PDF remark failed: '+e.message);});await assertSucceeds(save('co','co-review',{anchorKind:'Area',quote:'Scanned table',severity:'Good point'})).catch(e=>{throw Error('Co-supervisor PDF remark failed: '+e.message);});await assertSucceeds(save('sup','four-regions',{rects:Array.from({length:4},(_,i)=>({x:40,y:700-i*15,width:100,height:10}))})).catch(e=>{throw Error('Four-region PDF remark failed: '+e.message);});await assertFails(save('sup','five-regions',{rects:Array(5).fill({x:40,y:700,width:100,height:10})}));
