 await assertFails(save('admin','2026/2027','bad-previous'));await assertSucceeds(save('admin','2026/2027','second',{previousSession:'2025/2026',previousRevision:'first',previousDepartmentName:'Session Pilot'}));assert.equal((await getDoc(doc(student,'studentAccountRequests',uid))).data().session,'2025/2026');assert.equal((await getDoc(doc(anon,'registrationSessions',dept))).data().session,'2026/2027');
 const nextUid='session-applicant-next',nextEmail='session-next@example.edu',next=env.authenticatedContext(nextUid,{email:nextEmail}).firestore();await assertFails(setDoc(doc(next,'studentAccountRequests',nextUid),{...request,email:nextEmail}));await assertSucceeds(setDoc(doc(next,'studentAccountRequests',nextUid),{...request,email:nextEmail,session:'2026/2027'}));await assertFails(getDocs(collection(anon,'students')));
