 async function seedStudent(uid,email,departmentId='dept-a',session='2025/2026'){const id='attendance-'+uid;await env.withSecurityRulesDisabled(async c=>{const db=c.firestore();await setDoc(doc(db,'students',id),{departmentId,session,email});await setDoc(doc(db,'studentAccountRequests',uid),{status:'Approved',studentId:id,email,name:uid,matricNumber:'TEST/'+uid});await setDoc(doc(db,'studentPortalAccess',email),{active:true,studentId:id,departmentId,email,requestUid:uid});});return env.authenticatedContext(uid,{email,email_verified:true}).firestore();}
