 for(const uid of['admin','inactive-sup','unknown','foreign'])await assertFails(setDoc(doc(env.authenticatedContext(uid).firestore(),'classSessions',sid),{...metadata,ownerId:uid,ownerName:uid}));
 await assertFails(setDoc(doc(host,'classSessions',sid),{...metadata,windowMinutes:31}));await assertFails(setDoc(doc(host,'classSessions',sid),{...metadata,ownerId:'co'}));await assertSucceeds(setDoc(doc(host,'classSessions',sid),metadata));await assertSucceeds(setDoc(doc(hod,'classSessions','hod-class'),{...metadata,ownerId:'hod-a',ownerName:'hod-a'}));
 for(const db of[host,hod,student])await assertSucceeds(getDoc(doc(db,'classSessions',sid)));for(const uid of['co','admin','hod-b','foreign','inactive-sup'])await assertFails(getDoc(doc(env.authenticatedContext(uid).firestore(),'classSessions',sid)));
 await assertSucceeds(getDocs(query(collection(host,'classSessions'),where('departmentId','==','dept-a'),where('ownerId','==','sup'))));await assertSucceeds(getDocs(query(collection(hod,'classSessions'),where('departmentId','==','dept-a'))));await assertFails(getDocs(query(collection(host,'classSessions'),where('departmentId','==','dept-a'))));await assertFails(getDocs(collection(student,'classSessions')));
 await assertFails(getDoc(doc(env.unauthenticatedContext().firestore(),'classSessions',sid)));await assertFails(setDoc(doc(env.authenticatedContext('attendance-recreated',{email:'attendance@example.edu',email_verified:true}).firestore(),'classSessions',sid,'checkIns','attendance-attendance-recreated'),{studentId:'attendance-attendance-user',studentUid:'attendance-recreated',studentName:'attendance-user',matricNumber:'TEST/attendance-user',token,checkedAt:serverTimestamp()}));
 const key=doc(host,'classSessions',sid,'keys','current');await assertSucceeds(setDoc(key,{token,issuedAt:serverTimestamp()}));await assertSucceeds(getDoc(key));for(const db of[student,peer,hod,admin])await assertFails(getDoc(doc(db,'classSessions',sid,'keys','current')));await assertFails(setDoc(doc(student,'classSessions',sid,'keys','current'),{token,issuedAt:serverTimestamp()}));
 const receipt=(uid,changes={})=>({studentId:'attendance-'+uid,studentUid:uid,studentName:uid,matricNumber:'TEST/'+uid,token,checkedAt:serverTimestamp(),...changes});
 for(const changes of[{studentUid:'attendance-peer'},{token:'b'.repeat(32)},{studentId:'attendance-attendance-peer'},{studentName:'Impersonation'},{matricNumber:'TEST/another'},{checkedAt:new Timestamp(1,0)},{extra:'invalid'}])await assertFails(setDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user'),receipt('attendance-user',changes)));
 await assertFails(setDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-peer'),receipt('attendance-peer')));await assertFails(setDoc(doc(foreignStudent,'classSessions',sid,'checkIns','attendance-attendance-foreign'),receipt('attendance-foreign')));await assertFails(setDoc(doc(wrongSession,'classSessions',sid,'checkIns','attendance-attendance-old'),receipt('attendance-old')));await assertFails(setDoc(doc(env.authenticatedContext('attendance-user',{email:'attendance@example.edu',email_verified:false}).firestore(),'classSessions',sid,'checkIns','attendance-attendance-user'),receipt('attendance-user')));
 await env.withSecurityRulesDisabled(async c=>await setDoc(doc(c.firestore(),'classSessions',sid,'keys','current'),{token,issuedAt:Timestamp.fromMillis(Date.now()-61000)}));await assertFails(setDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user'),receipt('attendance-user')));await assertSucceeds(setDoc(key,{token,issuedAt:serverTimestamp()}));
 await assertSucceeds(setDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user'),receipt('attendance-user')));await assertFails(setDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user'),receipt('attendance-user')));await assertFails(deleteDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user')));await assertSucceeds(getDoc(doc(student,'classSessions',sid,'checkIns','attendance-attendance-user')));await assertFails(getDoc(doc(peer,'classSessions',sid,'checkIns','attendance-attendance-user')));await assertFails(getDocs(collection(student,'classSessions',sid,'checkIns')));for(const db of[host,hod])assert.equal((await assertSucceeds(getDocs(collection(db,'classSessions',sid,'checkIns')))).size,1);
 await assertFails(updateDoc(doc(hod,'classSessions',sid),{closed:true,closedAt:serverTimestamp()}));await assertFails(updateDoc(doc(host,'classSessions',sid),{title:'Rewritten'}));await assertFails(deleteDoc(doc(host,'classSessions',sid)));
