 await assertSucceeds(updateDoc(doc(host,'classSessions',sid),{closed:true,closedAt:serverTimestamp()}));await assertFails(setDoc(doc(peer,'classSessions',sid,'checkIns','attendance-attendance-peer'),receipt('attendance-peer')));await assertFails(setDoc(key,{token,issuedAt:serverTimestamp()}));await assertFails(updateDoc(doc(host,'classSessions',sid),{closed:false}));
 await env.withSecurityRulesDisabled(async c=>{const db=c.firestore();await setDoc(doc(db,'classSessions','expired-class'),{...metadata,createdAt:Timestamp.fromMillis(Date.now()-31*60000)});await setDoc(doc(db,'classSessions','expired-class','keys','current'),{token,issuedAt:Timestamp.now()});});await assertFails(setDoc(doc(peer,'classSessions','expired-class','checkIns','attendance-attendance-peer'),receipt('attendance-peer')));
 await env.withSecurityRulesDisabled(async c=>await updateDoc(doc(c.firestore(),'studentPortalAccess','attendance@example.edu'),{active:false}));await assertFails(getDoc(doc(rebound,'classSessions',sid,'checkIns','attendance-attendance-user')));
